export const getListEstudiosExternosUrl = (params?: ListEstudiosExternosParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/integraciones/phirit/estudios?${stringifiedParams}` : `/api/integraciones/phirit/estudios`
}

