export const getGetOcupacionTurnerasUrl = (params?: GetOcupacionTurnerasParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/dashboard/ocupacion-turneras?${stringifiedParams}` : `/api/dashboard/ocupacion-turneras`
}

